package niconico

// oauthCallbackHTMLTemplate は server/app/utils/OAuthCallbackResponse.py の HTML テンプレート。
// $status$ / $detail$ / $redirect_to$ を置換して使用する (Python 版と同じ置換順) 。
// この定数は testdata/generate_niconico_fixture.py が出力する HTML と一致することをテストで確認している。
const oauthCallbackHTMLTemplate = "\n        <!DOCTYPE html>\n        <html lang=\"ja\">\n        <head>\n            <meta charset=\"utf-8\">\n            <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n            <meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\">\n            <script>\n                window.onload = () => {\n                    // (PC) ポップアップ経由で OAuth 連携を行った場合\n                    if (window.opener) {\n                        window.opener.postMessage({\n                            'KonomiTV-OAuthPopup': {\n                                'status': $status$,\n                                'detail': '$detail$',\n                            }\n                        }, '*');\n                    // (スマホ・タブレット) リダイレクト経由で OAuth 連携を行った場合\n                    } else {\n                        location.href = `$redirect_to$#status=$status$&detail=${encodeURIComponent('$detail$')}`;\n                    }\n                };\n            </script>\n        </head>\n        <body style=\"background: #1E1310; color: #FFEAEA;\">\n        </body>\n        </html>\n        "
